fun main() {
    println(kotlin.math.floor(1.7))
    println(kotlin.math.ceil(1.2))
    println(kotlin.math.round(2.7))
    println(kotlin.math.round(2.3))
    println(kotlin.math.sqrt(16.0))
    println(kotlin.math.sin(0.0))
